 91	// name under a stricter constraint can re-derive the same observation, and
 92	// printing it twice would just look like a bug.
 93	func addDepWarning(plan *DepPlan, warning string) {
 94		if warning == "" || slices.Contains(plan.Warnings, warning) {
 95			return
 96		}
 97		plan.Warnings = append(plan.Warnings, warning)
 98	}
