207	// dependencySatisfied checks whether a requirement is already met, in
208	// order: managed install with manifest (version-checkable) → managed entry
209	// without manifest (local-dev, version unknown) → raw $PATH (version
210	// unknown). Note `entire plugin <verb>` runs with the user's original PATH
211	// (main.go restores it for built-ins), so LookPath here sees only
212	// raw-PATH plugins — managed entries are checked explicitly first.
213	func dependencySatisfied(req PluginRequirement) (satisfied bool, warning string, err error) {
214		m, err := LoadPluginManifest(req.Name)
215		if err != nil {
216			return false, "", err
217		}
218		if m != nil {
219			if req.MinVersion == "" || semver.Compare(canonicalSemver(m.Tag), canonicalSemver(req.MinVersion)) >= 0 {
220				return true, "", nil
221			}
222			return false, "", nil // triggers the upgrade path in planDeps
223		}
224		installed, err := FindInstalledPlugin(req.Name)
225		if err != nil {
226			return false, "", err
227		}
228		if installed != nil {
229			return true, unverifiableVersionWarning(req, "a local-dev install"), nil
230		}
231		if _, err := exec.LookPath(pluginBinaryPrefix + req.Name); err == nil {
232			return true, unverifiableVersionWarning(req, "$PATH"), nil
233		}
234		return false, "", nil
235	}
236	
237	func unverifiableVersionWarning(req PluginRequirement, source string) string {
238		if req.MinVersion == "" {
239			return ""
240		}
241		return fmt.Sprintf("dependency %q is satisfied from %s; cannot verify min_version %s", req.Name, source, req.MinVersion)
242	}
