260	// DependentsOf returns the names of managed plugins whose manifests list
261	// name as a requirement — the remove guard. Computed by scanning
262	// pkg/*/manifest.yml; no extra state to maintain.
263	func DependentsOf(name string) ([]string, error) {
264		manifests, err := ListPluginManifests()
265		if err != nil {
266			return nil, err
267		}
268		var out []string
269		for _, m := range manifests {
270			for _, req := range m.Requires {
271				if req.Name == name {
272					out = append(out, m.Name)
273					break
274				}
275			}
276		}
277		return out, nil
278	}
