363	// checkManagedBinaryIntegrity re-hashes a managed plugin's binary and
364	// compares it to the digest recorded at install time, catching a binary
365	// swapped out under the managed directory after install.
366	//
367	// This checks the pkg/ binary, which is the copy the manifest describes and
368	// the target bin/ links to. Where the bin/ entry is a copy rather than a link
369	// (Windows without Developer Mode), a tampered copy is not covered — the
370	// dangling/non-executable link check above is what guards that surface.
371	//
372	// A manifest without BinarySHA256 predates integrity recording, so there is
373	// nothing to compare and silence is correct; nagging about it would only tell
374	// the user to reinstall a plugin that is probably fine.
375	func checkManagedBinaryIntegrity(m *PluginManifest) []PluginDoctorIssue {
376		var issues []PluginDoctorIssue
377		if m.Unverified {
378			issues = append(issues, PluginDoctorIssue{
379				Plugin:  m.Name,
380				Problem: fmt.Sprintf("installed from %s without checksum verification (the release published no %s)", m.Tag, checksumsFileName),
381				Fix:     "if the author has since published checksums, re-run: entire plugin upgrade " + m.Name,
382			})
383		}
384		if m.BinarySHA256 == "" {
385			return issues
386		}
387		dir, err := PluginPkgDir(m.Name)
388		if err != nil {
389			return issues
390		}
391		binPath := filepath.Join(dir, pluginBinaryName(m.Name))
392		got, err := fileSHA256(binPath)
393		if err != nil {
394			issues = append(issues, PluginDoctorIssue{
395				Plugin:  m.Name,
396				Problem: "managed binary is missing or unreadable: " + err.Error(),
397				Fix:     fmt.Sprintf("reinstall: entire plugin install %s --force", m.RepoURL),
398			})
399			return issues
400		}
401		if !strings.EqualFold(got, m.BinarySHA256) {
402			issues = append(issues, PluginDoctorIssue{
403				Plugin:  m.Name,
404				Problem: "managed binary no longer matches the digest recorded at install; it was modified or replaced outside entire",
405				Fix:     fmt.Sprintf("reinstall from the recorded source: entire plugin install %s --force", m.RepoURL),
406			})
407		}
408		return issues
409	}
