411	// quarantinedPath returns the path to flag when the file (or its symlink
412	// target) carries com.apple.quarantine. Best-effort, macOS only; any error
413	// means "not quarantined". The attribute appears when a user manually
414	// drops a browser-downloaded binary into the managed dir — CLI downloads
415	// don't set it.
416	//
417	// Checking the bin entry is sufficient even though remote installs link
418	// bin/entire-<name> to the real binary under pkg/: macOS xattr follows
419	// symlinks by default (-s is the flag to act on the link itself), so both
420	// the probe here and the suggested `xattr -d` fix operate on the target.
421	func quarantinedPath(ctx context.Context, path string) string {
422		if runtime.GOOS != darwinGOOS {
423			return ""
424		}
425		out, err := exec.CommandContext(ctx, "xattr", "-p", "com.apple.quarantine", path).Output()
426		if err != nil || strings.TrimSpace(string(out)) == "" {
427			return ""
428		}
429		return path
430	}

