+		official := ""
+		if e.Official {
+			official = " [official]"
+		}
+		fmt.Fprintf(w, "%s %-20s %s%s\n", mark, e.Name, e.Description, official)
+	}
+	fmt.Fprintln(w, "\n* = installed. Install with 'entire plugin install <name>'.")
+}
